const body = JSON.stringify(meta);
const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36';

async function verify(url) {
  try {
    const r = await fetch(url, { headers: { accept: 'application/json', 'user-agent': UA } });
    const t = await r.text();
    let parsed = false;
    try { JSON.parse(t); parsed = true; } catch {}
    return { status: r.status, ct: r.headers.get('content-type'), parsed, head: t.slice(0, 80) };
  } catch (e) { return { err: String(e) }; }
}

// 1) paste.rs
try {
  const r = await fetch('https://paste.rs', { method: 'POST', body, headers: { 'content-type': 'text/plain', 'user-agent': UA } });
  const url = (await r.text()).trim();
  out.paste_rs = { status: r.status, url, verify: url.startsWith('http') ? await verify(url) : null };
} catch (e) { out.paste_rs = { err: String(e) }; }

// 2) dpaste.com
try {
  const fd = new URLSearchParams();
  fd.append('content', body);
  fd.append('syntax', 'json');
  fd.append('expiry_days', '365');
  const r = await fetch('https://dpaste.com/api/v2/', { method: 'POST', body: fd, headers: { 'user-agent': UA } });
  const url = (await r.text()).trim();
  out.dpaste = { status: r.status, url, verify: url.startsWith('http') ? await verify(url) : null };
} catch (e) { out.dpaste = { err: String(e) }; }

// 3) 0x0.st
