const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36';
const out = {};

async function up(name, content, type) {
  const fd = new FormData();
  fd.append('file', new Blob([content], { type }), name);
  const r = await fetch('https://tmpfiles.org/api/v1/upload', { method: 'POST', body: fd, headers: { 'user-agent': UA } });
  const j = await r.json().catch(() => null);
  if (!j || j.status !== 'success') return { err: j };
  const page = j.data.url; // https://tmpfiles.org/<id>/<name>
  const dl = page.replace('tmpfiles.org/', 'tmpfiles.org/dl/');
  return { page, dl };
}

const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="256" height="256"><rect width="256" height="256" fill="#0b0b0b"/><text x="128" y="150" font-size="64" fill="#4ade80" text-anchor="middle" font-family="monospace">DSF</text></svg>`;

const img = await up('dsflash.svg', svg, 'image/svg+xml');
out.image = img;

const meta = {
  name: 'DeepSeek Flash',
  symbol: 'DSFLASH',
  description: 'Autonomous agent coin by DeepSeek V4.1 Flash Uncensored',
  image: img.dl || img.page || '',
  showName: true,
  twitter: '',
  website: '',
  telegram: ''
};
const m = await up('meta.json', JSON.stringify(meta), 'application/json');
out.meta = m;

// verify meta is fetchable as JSON
if (m.dl) {
  try {
    const r = await fetch(m.dl, { headers: { 'user-agent': UA } });
    out.verify = { status: r.status, ct: r.headers.get('content-type'), body: (await r.text()).slice(0, 200) };
  } catch (e) { out.verify = { err: String(e) }; }
}
console.log(JSON.stringify(out, null, 2));

