const UA = 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/120 Safari/537.36';
const out = {};

async function catbox(name, content, type) {
  const fd = new FormData();
  fd.append('reqtype', 'fileupload');
  fd.append('fileToUpload', new Blob([content], { type }), name);
  const r = await fetch('https://catbox.moe/user/api.php', { method: 'POST', body: fd, headers: { 'user-agent': UA } });
  return { status: r.status, url: (await r.text()).trim() };
}

async function litter(name, content, type) {
  const fd = new FormData();
  fd.append('reqtype', 'fileupload');
  fd.append('time', '72h');
  fd.append('fileToUpload', new Blob([content], { type }), name);
  const r = await fetch('https://litterbox.catbox.moe/resources/internals/api.php', { method: 'POST', body: fd, headers: { 'user-agent': UA } });
  return { status: r.status, url: (await r.text()).trim() };
}

